package com.xuhang.mealops.inventory.api;
import java.math.BigDecimal; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import com.xuhang.mealops.inventory.application.InventoryConsumptionApplicationService; import com.xuhang.mealops.inventory.domain.InventoryConsumptionAllocation;
@RestController @RequestMapping("/api/v1/inventory/consumptions") public class InventoryConsumptionController { private final InventoryConsumptionApplicationService service; public InventoryConsumptionController(InventoryConsumptionApplicationService s){service=s;} public record Request(@NotNull @Positive Long ingredientId,@NotNull BigDecimal amount,@NotBlank String unit){} public record Allocation(int position,long batchId,BigDecimal amount,String unit,BigDecimal remainingAfter){} public record Response(long transactionId,long ingredientId,BigDecimal amount,String unit,java.util.List<Allocation> allocations){} @PostMapping public Response consume(@Valid @RequestBody Request r){var x=service.consume(r.ingredientId(),r.amount(),r.unit());return new Response(x.transactionId(),x.ingredientId(),x.quantity().amount(),x.quantity().unit().code(),x.allocations().stream().map(a->new Allocation(a.position(),a.batchId(),a.amount(),a.unit(),a.after())).toList());} }
